import React, {
  useEffect,
  useState
} from "react";

function Incidents() {
  const [incidents,
    setIncidents] =
    useState([]);

  useEffect(() => {
    const token =
      localStorage.getItem(
        "access_token"
      );

    fetch(
      "http://127.0.0.1:8000/incidents/",
      {
        headers: {
          Authorization:
            `Bearer ${token}`
        }
      }
    )
      .then((res) => res.json())
      .then((data) => {
        setIncidents(
          data.incidents || []
        );
      })
      .catch((err) =>
        console.error(err)
      );
  }, []);

  return (
    <div style={styles.main}>
      <h1>Incidents</h1>

      {incidents.map(
        (incident) => (
          <div
            key={incident.id}
            style={styles.card}
          >
            <h3>
              {incident.title}
            </h3>
          </div>
        )
      )}
    </div>
  );
}

const styles = {
  main: {
    flex: 1,
    padding: "30px"
  },
  card: {
    background: "#1e293b",
    padding: "20px",
    borderRadius: "10px",
    marginBottom: "15px"
  }
};

export default Incidents;
